namespace InventoryService.Events;

public class PartRequestedEvent { public Guid EventId { get; set; } public string EventType { get; set; } = string.Empty; public DateTime OccurredAt { get; set; } public string Source { get; set; } = string.Empty; public string? CorrelationId { get; set; } public PartRequestedData Data { get; set; } = new(); }
public class PartRequestedData { public int RequestId { get; set; } public int JobCardId { get; set; } public string JobCardNumber { get; set; } = string.Empty; public int SparePartId { get; set; } public int RequestedQuantity { get; set; } public string RequestingMechanicId { get; set; } = string.Empty; public string RequestingMechanicName { get; set; } = string.Empty; }
public class PartIssuedEvent { public Guid EventId { get; set; } = Guid.NewGuid(); public string EventType { get; set; } = "PartIssued"; public DateTime OccurredAt { get; set; } = DateTime.UtcNow; public string Source { get; set; } = "InventoryService"; public string? CorrelationId { get; set; } public PartIssuedData Data { get; set; } = new(); }
public class PartIssuedData { public int IssueId { get; set; } public int RequestId { get; set; } public int JobCardId { get; set; } public int SparePartId { get; set; } public string SparePartName { get; set; } = string.Empty; public int QuantityIssued { get; set; } public decimal UnitPrice { get; set; } public decimal TotalAmount { get; set; } }
